create or replace function catalog.initialize_custom_field_template(
  p_tenant_id uuid,
  p_template_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_template_key text := coalesce(nullif(btrim(p_template_id), ''), 'vet_pharmacy_default');
  v_template catalog.custom_field_templates%rowtype;
  v_group jsonb;
  v_field jsonb;
  v_group_id uuid;
  v_field_id uuid;
  v_name_normalized text;
  v_groups_created int := 0;
  v_fields_created int := 0;
  v_skipped_count int := 0;
begin
  perform catalog._assert_custom_fields_permission(p_tenant_id);

  select *
  into v_template
  from catalog.custom_field_templates t
  where t.template_key = v_template_key;

  if not found then
    raise exception 'validation_exception: Template not found.';
  end if;

  for v_group in
    select value
    from jsonb_array_elements(v_template.definition -> 'groups')
  loop
    v_name_normalized := catalog._normalize_custom_field_name(v_group ->> 'name');
    if v_name_normalized is null then
      continue;
    end if;

    select g.id
    into v_group_id
    from catalog.custom_field_groups g
    where g.tenant_id = p_tenant_id
      and g.name = v_name_normalized
      and g.status = 'active'
    limit 1;

    if v_group_id is null then
      insert into catalog.custom_field_groups (
        tenant_id,
        name,
        icon_key,
        sort_order,
        status
      )
      values (
        p_tenant_id,
        v_name_normalized,
        nullif(btrim(v_group ->> 'icon_key'), ''),
        (
          select coalesce(max(g.sort_order), -1) + 1
          from catalog.custom_field_groups g
          where g.tenant_id = p_tenant_id
        ),
        'active'
      )
      returning id into v_group_id;
      v_groups_created := v_groups_created + 1;
    else
      v_skipped_count := v_skipped_count + 1;
    end if;

    for v_field in
      select value
      from jsonb_array_elements(coalesce(v_group -> 'fields', '[]'::jsonb))
    loop
      v_name_normalized := catalog._normalize_custom_field_name(v_field ->> 'name');
      if v_name_normalized is null then
        continue;
      end if;

      if exists (
        select 1
        from catalog.custom_fields f
        where f.group_id = v_group_id
          and f.name = v_name_normalized
          and f.status = 'active'
      ) then
        v_skipped_count := v_skipped_count + 1;
        continue;
      end if;

      insert into catalog.custom_fields (
        tenant_id,
        group_id,
        name,
        field_type,
        sort_order,
        status
      )
      values (
        p_tenant_id,
        v_group_id,
        v_name_normalized,
        coalesce(nullif(btrim(v_field ->> 'field_type'), ''), 'text'),
        (
          select coalesce(max(f.sort_order), -1) + 1
          from catalog.custom_fields f
          where f.group_id = v_group_id
        ),
        'active'
      )
      returning id into v_field_id;
      v_fields_created := v_fields_created + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'groups_created', v_groups_created,
    'fields_created', v_fields_created,
    'skipped_count', v_skipped_count
  );
end;
$$;

create or replace function catalog.upsert_custom_field_group(
  p_tenant_id uuid,
  p_name text,
  p_group_id uuid default null,
  p_icon_key text default null,
  p_is_active boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_group_id uuid := p_group_id;
  v_status text := case when coalesce(p_is_active, true) then 'active' else 'inactive' end;
  v_duplicate_id uuid;
begin
  perform catalog._assert_custom_fields_permission(p_tenant_id);

  v_name := catalog._normalize_custom_field_name(p_name);
  if v_name is null then
    raise exception 'validation_exception: Group name must not be empty.';
  end if;

  if v_group_id is not null then
    if not exists (
      select 1
      from catalog.custom_field_groups g
      where g.id = v_group_id
        and g.tenant_id = p_tenant_id
    ) then
      raise exception 'custom field group not found';
    end if;

    select g.id
    into v_duplicate_id
    from catalog.custom_field_groups g
    where g.tenant_id = p_tenant_id
      and g.name = v_name
      and g.status = 'active'
      and g.id <> v_group_id
    limit 1;

    if v_duplicate_id is not null then
      raise exception 'duplicate custom field group name "%"', v_name;
    end if;

    update catalog.custom_field_groups g
    set
      name = v_name,
      icon_key = nullif(btrim(p_icon_key), ''),
      status = v_status,
      updated_at = now()
    where g.id = v_group_id;
  else
    select g.id
    into v_duplicate_id
    from catalog.custom_field_groups g
    where g.tenant_id = p_tenant_id
      and g.name = v_name
      and g.status = 'active'
    limit 1;

    if v_duplicate_id is not null then
      raise exception 'duplicate custom field group name "%"', v_name;
    end if;

    insert into catalog.custom_field_groups (
      tenant_id,
      name,
      icon_key,
      sort_order,
      status
    )
    values (
      p_tenant_id,
      v_name,
      nullif(btrim(p_icon_key), ''),
      (
        select coalesce(max(g.sort_order), -1) + 1
        from catalog.custom_field_groups g
        where g.tenant_id = p_tenant_id
      ),
      v_status
    )
    returning id into v_group_id;
  end if;

  return catalog._custom_field_group_to_json(v_group_id);
end;
$$;

create or replace function catalog.upsert_custom_field(
  p_tenant_id uuid,
  p_group_id uuid,
  p_name text,
  p_field_type text,
  p_field_id uuid default null,
  p_options jsonb default '[]'::jsonb,
  p_is_active boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_name text;
  v_field_id uuid := p_field_id;
  v_status text := case when coalesce(p_is_active, true) then 'active' else 'inactive' end;
  v_duplicate_id uuid;
  v_option jsonb;
  v_option_index int := 0;
begin
  perform catalog._assert_custom_fields_permission(p_tenant_id);

  if not exists (
    select 1
    from catalog.custom_field_groups g
    where g.id = p_group_id
      and g.tenant_id = p_tenant_id
  ) then
    raise exception 'custom field group not found';
  end if;

  v_name := catalog._normalize_custom_field_name(p_name);
  if v_name is null then
    raise exception 'validation_exception: Field name must not be empty.';
  end if;

  if coalesce(nullif(btrim(p_field_type), ''), '') not in (
    'text', 'number', 'date', 'boolean', 'singleSelect'
  ) then
    raise exception 'validation_exception: Unsupported field type.';
  end if;

  if p_field_type = 'singleSelect'
     and (
       p_options is null
       or jsonb_array_length(p_options) = 0
     )
     and v_field_id is null then
    raise exception 'validation_exception: Single select field requires options.';
  end if;

  if v_field_id is not null then
    if not exists (
      select 1
      from catalog.custom_fields f
      where f.id = v_field_id
        and f.group_id = p_group_id
        and f.tenant_id = p_tenant_id
    ) then
      raise exception 'custom field not found';
    end if;

    select f.id
    into v_duplicate_id
    from catalog.custom_fields f
    where f.group_id = p_group_id
      and f.name = v_name
      and f.status = 'active'
      and f.id <> v_field_id
    limit 1;

    if v_duplicate_id is not null then
      raise exception 'duplicate custom field name "%"', v_name;
    end if;

    update catalog.custom_fields f
    set
      name = v_name,
      field_type = p_field_type,
      status = v_status,
      updated_at = now()
    where f.id = v_field_id;

    delete from catalog.custom_field_options o
    where o.field_id = v_field_id;
  else
    select f.id
    into v_duplicate_id
    from catalog.custom_fields f
    where f.group_id = p_group_id
      and f.name = v_name
      and f.status = 'active'
    limit 1;

    if v_duplicate_id is not null then
      raise exception 'duplicate custom field name "%"', v_name;
    end if;

    insert into catalog.custom_fields (
      tenant_id,
      group_id,
      name,
      field_type,
      sort_order,
      status
    )
    values (
      p_tenant_id,
      p_group_id,
      v_name,
      p_field_type,
      (
        select coalesce(max(f.sort_order), -1) + 1
        from catalog.custom_fields f
        where f.group_id = p_group_id
      ),
      v_status
    )
    returning id into v_field_id;
  end if;

  if p_field_type = 'singleSelect' and p_options is not null then
    for v_option in
      select value
      from jsonb_array_elements(p_options)
    loop
      insert into catalog.custom_field_options (
        tenant_id,
        field_id,
        label,
        sort_order,
        is_active
      )
      values (
        p_tenant_id,
        v_field_id,
        btrim(v_option ->> 'label'),
        coalesce((v_option ->> 'sort_order')::int, v_option_index),
        coalesce((v_option ->> 'is_active')::boolean, true)
      );
      v_option_index := v_option_index + 1;
    end loop;
  end if;

  return catalog._custom_field_to_json(v_field_id);
end;
$$;
